111: /**
112:  * Resolves the article requested by an external deep link.  The article the
113:  * reader asked for stays the visible destination; the encouragement never
114:  * replaces it.
115:  */
116: export function parseExternalArticle(uri: string): ExternalArticle {
117:   const empty: ExternalArticle = { language: '', title: '', article: '' };
118:   const trimmed: string = uri.trim();
119:   if (trimmed.length === 0) {
120:     return empty;
121:   }
122:   let rest: string = trimmed;
123:   const schemeIndex: number = rest.indexOf('://');
124:   if (schemeIndex >= 0) {
125:     rest = rest.substring(schemeIndex + 3);
126:   }
127:   let host: string = rest;
128:   let path: string = '';
129:   const slashIndex: number = rest.indexOf('/');
130:   if (slashIndex >= 0) {
131:     host = rest.substring(0, slashIndex);
132:     path = rest.substring(slashIndex + 1);
133:   }
134:   const queryIndex: number = path.indexOf('?');
135:   if (queryIndex >= 0) {
136:     path = path.substring(0, queryIndex);
137:   }
138:   const segments: string[] = path.split('/');
139:   let language: string = host.split('.')[0];
140:   if (language.indexOf('wikipedia') >= 0 || language.indexOf('wikimedia') >= 0) {
141:     language = '';
142:   }
143:   let title: string = '';
144:   for (let index = segments.length - 1; index >= 0; index--) {
145:     if (segments[index].length > 0) {
146:       title = segments[index];
147:       break;
148:     }
149:   }
150:   if (title.indexOf('wiki=') === 0) {
151:     title = title.substring(5);
152:   }
153:   if (title.length === 0) {
154:     return { language: language, title: '', article: language };
155:   }
156:   const article: string = language.length > 0 ? language + ':' + title : title;
157:   return { language: language, title: title, article: article };
158: }
