330:   // ------------------------------------------------------------------ intents
331: 
332:   private isExternalLinkIntent(
333:     name: string, event: Record<string, Object>, declaredLaunch: EvergreenLaunchKind | undefined): boolean {
334:     if (declaredLaunch === EVERGREEN_LAUNCH_EXTERNAL_ARTICLE) {
335:       return true;
336:     }
337:     return containsAny(name, ['deeplink', 'externalarticle', 'external', 'openuri', 'viewarticle']);
338:   }
339: 
340:   private isRelaunchIntent(name: string): boolean {
341:     return containsAny(name, ['relaunch', 'restart', 'recreate', 'coldstart', 'reopen']);
342:   }
343: 
344:   private isResumeIntent(name: string): boolean {
345:     return containsAny(name, ['resume', 'foreground', 'launch', 'startapp', 'continue']);
346:   }
347: 
348:   private isAuthenticationIntent(name: string, event: Record<string, Object>): boolean {
349:     if (containsAny(name, ['auth', 'accountcreation', 'createaccount', 'register', 'signup', 'signin',
350:       'login', 'createnew'])) {
351:       return true;
352:     }
353:     return this.authenticationRequested && firstText(event, AUTH_RESULT_KEYS).length > 0;
354:   }
355: 
356:   private mentionsAccountCreation(name: string): boolean {
357:     if (containsAny(name, ['cancel', 'abort', 'fail', 'error', 'skip'])) {
358:       return false;
359:     }
360:     return containsAny(name, ['createaccount', 'register', 'signup', 'signin', 'login', 'auth'])
361:       || (name.indexOf('create') >= 0 && name.indexOf('account') >= 0);
362:   }
363: 
364:   private declaredLaunchOf(event: Record<string, Object>): EvergreenLaunchKind | undefined {
365:     const raw: string = firstText(event, ['launch', 'launchtype', 'intent', 'type', 'action']);
366:     if (raw.length === 0) {
367:       return undefined;
368:     }
369:     return parseLaunchKind(raw);
370:   }
371: 
372:   private uriOf(event: Record<string, Object>): string {
373:     const raw: string = firstText(event, ['uri', 'deeplink', 'deeplinkuri', 'url', 'target']);
374:     return raw.length > 0 ? raw : this.deepLinkUri;
375:   }
376: 
377:   private authenticationResultOf(event: Record<string, Object>, name: string): string {
378:     const explicit: string = firstText(event, AUTH_RESULT_KEYS);
379:     if (explicit.length > 0) {
380:       return explicit.toLowerCase();
381:     }
382:     if (containsAny(name, ['cancel', 'abort'])) {
383:       return 'cancelled';
384:     }
385:     if (containsAny(name, ['fail', 'error'])) {
386:       return 'failed';
387:     }
388:     if (containsAny(name, ['success'])) {
389:       return 'success_permanent_account';
390:     }
391:     if (this.authenticationRequested && containsAny(name, ['complete', 'completed', 'finish', 'finished', 'result'])) {
392:       return 'success_permanent_account';
393:     }
394:     return '';
395:   }
