397:   private async handleAuthentication(name: string, event: Record<string, Object>): Promise<void> {
398:     if (this.mentionsAccountCreation(name)) {
399:       await this.startAuthentication();
400:     }
401:     const result: string = this.authenticationResultOf(event, name);
402:     if (result.length > 0) {
403:       await this.completeAuthentication(result);
404:       return;
405:     }
406:     if (this.authenticationActive) {
407:       await this.evaluateLaunch(this.launchType);
408:     }
409:   }
