413:   /** Ordinary launch / foreground resume: show the screen and record one impression. */
414:   private async resume(): Promise<void> {
415:     if (this.encouragementVisible) {
416:       // The screen is already on top of the reader surface.  Opening it again
417:       // must not produce a second impression.
418:       return;
419:     }
420:     const result: EvergreenEligibilityResult = await this.evaluateLaunch(this.launchType);
421:     if (!result.shouldShow) {
422:       return;
423:     }
424:     this.encouragementVisible = true;
425:     this.encouragementState = result.reason;
426:     await this.recordImpression(result);
427:   }
