458:   /** The dismiss control of the screen: a terminal opt-out that survives restarts. */
459:   private async handlePermanentClose(): Promise<void> {
460:     this.closeEncouragementSurface();
461:     this.encouragementState = 'dismissed';
462:     this.permanentlyDismissed = true;
463:     await this.persistState();
464:     await this.emit({
465:       name: EFFECT_NAME_ENCOURAGEMENT,
466:       interaction: 'close',
467:       count: this.impressions,
