473:   private async startAuthentication(): Promise<void> {
474:     this.authenticationRequested = true;
475:     this.authenticationCreateAccountFirst = true;
476:     this.authenticationActive = true;
477:     this.authenticationCompleted = false;
478:     this.authenticationSucceeded = false;
479:     this.authenticationResult = '';
480:     await this.emit({
481:       name: EFFECT_NAME_AUTHENTICATION,
482:       interaction: 'create_account',
483:       createAccountFirst: true,
484:       source: EFFECT_SOURCE
485:     });
486:   }
