488:   /**
489:    * Applies the result reported by the authentication leaf.  Only a permanent
490:    * registration suppresses the encouragement; leaving the flow without a
491:    * success result returns control and claims nothing.
492:    */
493:   private async completeAuthentication(rawResult: string): Promise<void> {
494:     const result: string = rawResult.trim().toLowerCase();
495:     this.authenticationActive = false;
496:     this.authenticationCompleted = true;
497:     this.authenticationResult = result;
498:     const temporary: boolean = result.indexOf('temp') >= 0;
499:     const permanent: boolean = result.indexOf('permanent') >= 0 || result.indexOf('register') >= 0
500:       || (result.indexOf('success') >= 0 && !temporary)
501:       || result.indexOf('loggedin') >= 0 || result.indexOf('signedin') >= 0;
502:     if (permanent || (temporary && result.indexOf('success') >= 0)) {
503:       this.authenticationSucceeded = true;
504:       if (!temporary) {
505:         this.account = EVERGREEN_ACCOUNT_REGISTERED;
506:       }
507:       this.closeEncouragementSurface();
508:       this.encouragementState = 'completed';
509:       await this.evaluateLaunch(this.launchType);
510:       this.updatePostRelaunchDecision();
511:       await this.emit({
512:         name: EFFECT_NAME_ENCOURAGEMENT,
513:         interaction: 'create_account_result',
514:         result: result,
515:         source: EFFECT_SOURCE
516:       });
517:       return;
518:     }
519:     this.authenticationSucceeded = false;
520:     this.encouragementState = this.encouragementVisible ? 'shown' : 'deferred';
521:     await this.emit({
522:       name: EFFECT_NAME_ENCOURAGEMENT,
523:       interaction: this.isCancellation(result) ? 'create_account_cancelled' : 'create_account_failed',
524:       result: result,
525:       source: EFFECT_SOURCE
526:     });
527:   }
528: 
529:   private isCancellation(result: string): boolean {
530:     return containsAny(result, ['cancel', 'abort', 'dismiss', 'leave', 'back', 'closed']) || result.length === 0;
531:   }
