533:   /**
534:    * External article routing.  It takes precedence over the encouragement and
535:    * leaves every impression counter untouched.
536:    */
537:   private async handleExternalArticle(uri: string): Promise<void> {
538:     this.launchType = EVERGREEN_LAUNCH_EXTERNAL_ARTICLE;
539:     this.deepLinkUri = uri.length > 0 ? uri : this.deepLinkUri;
540:     const requested: ExternalArticle = parseExternalArticle(this.deepLinkUri);
541:     this.article = requested.article;
542:     this.articleTitle = requested.title;
543:     this.articleLanguage = requested.language;
544:     this.surface = 'article';
545:     this.closeEncouragementSurface();
546:     if (!this.permanentlyDismissed && this.account !== EVERGREEN_ACCOUNT_REGISTERED) {
547:       this.encouragementState = 'suppressed_by_routing';
548:     }
549:     await this.evaluateLaunch(EVERGREEN_LAUNCH_EXTERNAL_ARTICLE);
550:     await this.emit({ name: EFFECT_NAME_EXTERNAL_ARTICLE, source: 'external_article_deep_link' });
551:   }
