553:   /** Application (or activity) recreation: reload durable state and re-decide. */
554:   private async relaunch(): Promise<void> {
555:     try {
556:       await this.reloadFromPersistence();
557:     } catch (error) {
558:       this.recoverFromFailure(error, 'relaunch');
559:     }
560:     this.launchType = EVERGREEN_LAUNCH_ORDINARY;
561:     this.deepLinkUri = '';
562:     this.article = '';
563:     this.articleTitle = '';
564:     this.articleLanguage = '';
565:     this.surface = 'main';
566:     this.closeEncouragementSurface();
567:     const result: EvergreenEligibilityResult = await this.evaluateLaunch(EVERGREEN_LAUNCH_ORDINARY);
568:     this.decisionAfterRelaunch = this.decisionRecord(result);
569:     if (result.shouldShow) {
570:       this.encouragementVisible = true;
571:       this.encouragementState = result.reason;
572:       await this.recordImpression(result);
573:     } else {
574:       this.encouragementState = this.encouragementStateOf(result);
575:     }
576:   }
