578:   private encouragementStateOf(result: EvergreenEligibilityResult): string {
579:     if (this.permanentlyDismissed) {
580:       return 'dismissed';
581:     }
582:     if (this.account === EVERGREEN_ACCOUNT_REGISTERED) {
583:       return 'completed';
584:     }
585:     return 'suppressed';
586:   }
