643:     record['minimumEarliestDayAgeDays'] = result.minimumEarliestDayAgeDays;
644:     record['minimumReturnReadingDays'] = result.minimumReturnReadingDays;
645:     record['readingDaysInWindow'] = result.readingDaysInWindow.join(',');
646:     record['readingDayCount'] = result.readingDayCount;
647:     record['returnReadingDays'] = result.returnReadingDays.join(',');
