660:   /**
661:    * Keeps the "what would a recreated application decide?" answer in step with
662:    * the durable state, so the page owner can report it without another write.
663:    */
664:   private updatePostRelaunchDecision(): void {
665:     try {
666:       this.decisionAfterRelaunch = this.decisionRecord(this.evaluate(EVERGREEN_LAUNCH_ORDINARY));
667:     } catch (error) {
668:       this.decisionAfterRelaunch = { 'evaluated': true, 'shouldShow': false, 'reason': 'evaluation_failed' };
669:     }
670:   }
