672:   private persistedState(): EvergreenPersistedState {
673:     return {
674:       impressions: this.impressions,
675:       lastImpressionDate: this.lastImpressionDate,
676:       permanentlyDismissed: this.permanentlyDismissed,
677:       savedCount: this.savedCount,
678:       readingHistoryJson: this.history.toJson()
679:     };
680:   }
