682:   /** Installs the launch snapshot as the durable state of the file. */
683:   private async seedPersistence(): Promise<void> {
684:     if (this.preferences === undefined) {
685:       return;
686:     }
687:     const state: EvergreenPersistedState = this.persistedState();
688:     try {
689:       await this.preferences.seed(state);
690:       this.persistence = await this.preferences.snapshotRecord();
691:     } catch (error) {
692:       this.lastFailure = 'seedPersistence: ' + String(error);
693:       this.persistence = this.persistenceRecord(state);
694:     }
695:     this.updatePostRelaunchDecision();
696:   }
697: 
698:   private async persistState(): Promise<void> {
699:     if (this.preferences === undefined) {
700:       return;
701:     }
702:     const state: EvergreenPersistedState = this.persistedState();
703:     try {
704:       await this.preferences.saveState(state);
705:       this.persistence = await this.preferences.snapshotRecord();
706:     } catch (error) {
707:       this.lastFailure = 'persistState: ' + String(error);
708:       this.persistence = this.persistenceRecord(state);
709:     }
710:     this.updatePostRelaunchDecision();
711:   }
712: 
713:   private async persistHistory(): Promise<void> {
714:     if (this.preferences === undefined) {
715:       return;
716:     }
717:     try {
718:       await this.preferences.saveReadingHistory(this.history.toJson(), this.savedCount);
719:       this.persistence = await this.preferences.snapshotRecord();
720:     } catch (error) {
721:       this.lastFailure = 'persistHistory: ' + String(error);
722:     }
723:     this.updatePostRelaunchDecision();
724:   }
