726:   private async reloadFromPersistence(): Promise<void> {
727:     if (this.preferences === undefined) {
728:       return;
729:     }
730:     const state: EvergreenPersistedState = await this.preferences.reload();
731:     this.impressions = state.impressions;
732:     this.lastImpressionDate = state.lastImpressionDate;
733:     this.permanentlyDismissed = state.permanentlyDismissed;
734:     this.savedCount = state.savedCount;
735:     if (state.readingHistoryJson.length > 0) {
736:       this.history.restoreFromJson(state.readingHistoryJson);
737:     }
738:     this.persistence = await this.preferences.snapshotRecord();
739:     this.updatePostRelaunchDecision();
740:   }
