742:   private persistenceRecord(state: EvergreenPersistedState): Record<string, Object> {
743:     const record: Record<string, Object> = {};
744:     record['impressions'] = state.impressions;
745:     record['lastImpressionDate'] = state.lastImpressionDate;
746:     record['permanentlyDismissed'] = state.permanentlyDismissed;
747:     record['savedCount'] = state.savedCount;
748:     record['durable'] = false;
749:     return record;
750:   }
