752:   /** Showing the screen records one impression with its local date. */
753:   private async recordImpression(result: EvergreenEligibilityResult): Promise<void> {
754:     this.impressions += 1;
755:     this.lastImpressionDate = this.clockDay();
756:     await this.persistState();
757:     await this.emit({
758:       name: EFFECT_NAME_ENCOURAGEMENT,
759:       interaction: result.reason,
760:       count: this.impressions,
761:       maximum: this.thresholds.maximumImpressions,
762:       historyCutoffDays: this.thresholds.historyWindowDays,
763:       qualifyingDays: this.thresholds.minimumDistinctReadingDays,
764:       source: EFFECT_SOURCE
765:     });
766:   }
