768:   // ------------------------------------------------------------------- leaves
769: 
770:   private async emit(effect: EvergreenEffect): Promise<void> {
771:     this.lastEffect = effect.name;
772:     this.effectsEmitted += 1;
773:     const input: EvergreenInput | undefined = this.input;
774:     if (input === undefined || input.leaf === undefined) {
775:       return;
776:     }
777:     const leaf: EvergreenLeaf = input.leaf;
778:     try {
779:       await leaf.emit(effect);
780:     } catch (error) {
781:       // Analytics and authentication are external leaves: a failing leaf must
782:       // never take the application surface down with it.
783:       this.lastFailure = 'emit: ' + String(error);
784:     }
785:   }
786: 
787:   private recoverFromFailure(error: Object, intent: string): void {
788:     this.lastFailure = intent + ': ' + String(error);
789:     console.error('EvergreenStore: ' + this.lastFailure);
790:     this.encouragementVisible = false;
791:     this.authenticationActive = false;
792:     this.surface = this.surface.length > 0 ? this.surface : 'main';
793:   }
794: 
795:   // ------------------------------------------------------------------ records
796: 
797:   private syncRecords(): void {
798:     this.state = this.buildState();
799:     this.historyDayList = this.history.distinctDays();
800:     this.routing = this.buildRouting();
801:   }
802: 
803:   private windowBounds(): number[] {
804:     const parsed: EvergreenCalendarDate | undefined = parseCalendarDate(this.clockDay());
805:     const today: EvergreenCalendarDate = parsed !== undefined ? parsed : { year: 1970, month: 1, day: 1 };
806:     const epoch: number = toEpochDay(today);
807:     return [epoch - this.thresholds.historyWindowDays, epoch];
808:   }
809: 
810:   private buildState(): Record<string, Object> {
811:     const bounds: number[] = this.windowBounds();
812:     const record: Record<string, Object> = {};
813:     record['surface'] = this.surface;
814:     record['accountEncouragementVisible'] = this.encouragementVisible;
815:     record['visibleSurface'] = this.encouragementVisible ? 'account_encouragement' : this.surface;
816:     record['account'] = this.account;
817:     record['encouragementState'] = this.encouragementState;
818:     record['today'] = this.clockDay();
819:     record['launchType'] = this.launchType;
820:     record['deepLinkUri'] = this.deepLinkUri;
821:     record['article'] = this.surface === 'article' ? this.article : '';
822:     record['articleTitle'] = this.surface === 'article' ? this.articleTitle : '';
823:     record['articleLanguage'] = this.surface === 'article' ? this.articleLanguage : '';
824:     record['mounted'] = this.mounted;
825:     record['featureAvailable'] = this.featureEnabled;
826:     record['effectsEmitted'] = this.effectsEmitted;
827:     record['lastEffect'] = this.lastEffect;
828:     record['lastFailure'] = this.lastFailure;
829: 
830:     const encouragement: Record<string, Object> = {};
831:     encouragement['visible'] = this.encouragementVisible;
832:     encouragement['state'] = this.encouragementState;
833:     encouragement['impressionCount'] = this.impressions;
834:     encouragement['maximumImpressions'] = this.thresholds.maximumImpressions;
835:     encouragement['lastImpressionDate'] = this.lastImpressionDate;
836:     encouragement['permanentlyDismissed'] = this.permanentlyDismissed;
837:     encouragement['historyWindowDays'] = this.thresholds.historyWindowDays;
838:     encouragement['readingDayCount'] = this.history.distinctDaysInWindow(bounds[0], bounds[1]).length;
839:     encouragement['articlesRead'] = this.history.totalReads();
840:     encouragement['articlesReadInWindow'] = this.history.totalReadsInWindow(bounds[0], bounds[1]);
841:     encouragement['savedCount'] = this.savedCount;
842:     record['encouragement'] = encouragement;
843: 
844:     const authentication: Record<string, Object> = {};
845:     authentication['requested'] = this.authenticationRequested;
846:     authentication['createAccountFirst'] = this.authenticationCreateAccountFirst;
847:     authentication['active'] = this.authenticationActive;
848:     authentication['completed'] = this.authenticationCompleted;
849:     authentication['succeeded'] = this.authenticationSucceeded;
850:     authentication['result'] = this.authenticationResult;
851:     record['authentication'] = authentication;
852:     return record;
853:   }
854: 
855:   private buildRouting(): Record<string, Object> {
856:     const record: Record<string, Object> = {};
