123: function distinctDaysInWindow(
124:   readingDays: string[], windowStart: number, today: number): string[] {
125:   const result: string[] = [];
126:   const seen: number[] = [];
127:   for (let index = 0; index < readingDays.length; index++) {
128:     const parsed: EvergreenCalendarDate | undefined = parseCalendarDate(readingDays[index]);
129:     if (parsed === undefined) {
130:       continue;
131:     }
132:     const epoch: number = toEpochDay(parsed);
133:     if (epoch < windowStart || epoch > today) {
134:       continue;
135:     }
136:     if (seen.indexOf(epoch) === -1) {
137:       seen.push(epoch);
138:       result.push(formatCalendarDate(parsed));
139:     }
140:   }
141:   result.sort((left: string, right: string): number => (left < right ? -1 : (left > right ? 1 : 0)));
142:   return result;
143: }
