184: export function findEvergreenQualifyingPair(
185:   daysInWindow: string[], today: number, thresholds: EvergreenThresholds): EvergreenQualifyingPair | undefined {
186:   if (daysInWindow.length < thresholds.minimumDistinctReadingDays) {
187:     return undefined;
188:   }
189:   for (let earlier = 0; earlier < daysInWindow.length; earlier++) {
190:     const earlierDate: EvergreenCalendarDate | undefined = parseCalendarDate(daysInWindow[earlier]);
191:     if (earlierDate === undefined) {
192:       continue;
193:     }
194:     if (today - toEpochDay(earlierDate) < thresholds.minimumEarliestDayAgeDays) {
195:       continue;
196:     }
197:     for (let later = earlier + 1; later < daysInWindow.length; later++) {
198:       const laterDate: EvergreenCalendarDate | undefined = parseCalendarDate(daysInWindow[later]);
199:       if (laterDate === undefined) {
200:         continue;
201:       }
202:       if (toEpochDay(laterDate) - toEpochDay(earlierDate) < thresholds.maximumDaysApart) {
203:         return { earliestDay: daysInWindow[earlier], latestDay: daysInWindow[later] };
