172:     async aboutToAppear(): Promise<void> {
173:         const owner: EvergreenPageOwner = this.createRuntimeOwner();
174:         this.attachedOwner = owner;
175:         EvergreenLaunchContext.attach(owner);
176:         const context: common.UIAbilityContext | undefined = this.hostContext();
177:         if (context === undefined || this.mounted) {
178:             return;
179:         }
180:         this.mounted = true;
181:         try {
182:             await owner.mount(context, EvergreenLaunchContext.productionInput(context));
183:             this.applyState();
184:             if (this.externalMountObserved) {
185:                 // Another owner took over the page while it was being created.
186:                 return;
187:             }
188:             // An ordinary foreground launch is where the encouragement is considered.
189:             await owner.dispatch({ 'name': 'resumeApplication' });
190:         }
191:         catch (error) {
192:             console.error('Index: mounting the evergreen account encouragement failed: ' + String(error));
193:         }
194:         this.applyState();
195:     }
