224:     /** Personalised counts, derived from the application's own stores. */
225:     private summaryFrom(state: Record<string, Object>): string {
226:         const details: Object | undefined = state['encouragement'];
227:         if (details === undefined || details === null || typeof details !== 'object') {
228:             return '';
229:         }
230:         const record: Record<string, Object> = details as Record<string, Object>;
231:         const days: number = Number(String(record['readingDayCount']));
232:         const reads: number = Number(String(record['articlesReadInWindow']));
233:         const saved: number = Number(String(record['savedCount']));
234:         const impressions: number = Number(String(record['impressionCount']));
235:         return 'You have read ' + String(reads) + ' article opens on ' + String(days) + ' recent days, '
236:             + String(saved) + ' saved. Encouragement ' + String(impressions) + ' of 2 shown.';
237:     }
238:     private authenticationPendingFrom(state: Record<string, Object>): boolean {
239:         const details: Object | undefined = state['authentication'];
240:         if (details === undefined || details === null || typeof details !== 'object') {
241:             return false;
242:         }
243:         return (details as Record<string, Object>)['active'] === true;
244:     }
